import subprocess
for scope in ('--local','--global','--system'):
    try:
        raw=subprocess.check_output(['git','config',scope,'--null','--list'])
    except subprocess.CalledProcessError:
        continue
    for e in raw.split(b'\0'):
        if not e or b'=' not in e: continue
        k,v=e.split(b'=',1)
        if k.startswith(b'url.') or k in (b'remote.origin.url', b'remote.origin.pushurl'):
            value=v.decode('utf-8','replace')
            value=value.replace('x-access-token:', 'x-access-token:***@') if 'x-access-token:' in value else value
            if 'github.com' in value or 'rork-' in value or k.startswith(b'url.'):
                print(scope, k.decode('utf-8','replace'), value[:180])
